 as x(slot_id text,position integer,stimulus_id text);
do $$ begin
 if (select count(*) from matched100v5_import)<>100 or (select count(distinct submission_id) from matched100v5_import)<>100
   or (select count(*) from matched100v5_plan_import)<>300 then raise exception 'Material count mismatch'; end if;
 if exists(select 1 from matched100v5_import where word_minimum<>60 or word_limit is not null or prompt_sha256<>encode(extensions.digest(prompt_text,'sha256'),'hex'))
   then raise exception 'Invalid material digest or word limit'; end if;
 if exists(select slot_id from matched100v5_plan_import group by slot_id having count(distinct stimulus_id)<>3)
   or exists(select stimulus_id from matched100v5_plan_import group by stimulus_id having count(distinct slot_id)<>3)
   or exists(select stimulus_id,position from matched100v5_plan_import group by stimulus_id,position having count(*)<>1)
 then raise exception 'Assignment is not balanced'; end if;
end $$;
insert into public.matched100v5_posts select stimulus_id,submission_id,prompt_text,prompt_sha256 from matched100v5_import on conflict do nothing;
insert into public.matched100v5_slots select distinct slot_id from matched100v5_plan_import on conflict do nothing;
insert into public.matched100v5_plan select * from matched100v5_plan_import on conflict do nothing;
insert into public.matched100v5_materials(version,stimulus_id,prompt_text,prompt_sha256,body_sha256,word_minimum,word_limit)
 select 'private100-study1matched-min60-20261026-v5',stimulus_id,prompt_text,prompt_sha256,body_sha256,word_minimum,word_limit from matched100v5_import on conflict do nothing;
do $$ begin
 if (select count(*) from public.matched100v5_posts)<>100 or (select count(*) from public.matched100v5_slots)<>100
   or (select count(*) from public.matched100v5_plan)<>300 or (select count(*) from public.matched100v5_materials)<>100
 then raise exception 'Unexpected existing cohort'; end if;
 if exists(select 1 from matched100v5_import i join public.matched100v5_posts p using(stimulus_id)
   where i.submission_id<>p.submission_id or i.prompt_text<>p.prompt_text or i.prompt_sha256<>p.prompt_sha256)
   or exists(select 1 from matched100v5_import i join public.matched100v5_materials m using(stimulus_id)
   where i.prompt_text<>m.prompt_text or i.prompt_sha256<>m.prompt_sha256 or i.body_sha256<>m.body_sha256 or i.word_minimum is distinct from m.word_minimum or i.word_limit is distinct from m.word_limit)
 then raise exception 'Existing material differs; cohorts are immutable'; end if;
 if exists(select 1 from matched100v5_plan_import i left join public.matched100v5_plan p using(slot_id,position,stimulus_id) where p.slot_id is null)
 then raise exception 'Existing assignment differs'; end if;
end $$;
update public.matched100v5_settings set version='private100-study1matched-min60-20261026-v5',consent_version='private100-study1matched-min60-v5' where id;
commit;
select version,recruitment_open,(select count(*) from public.matched100v5_posts) as posts,
 (select count(*) from public.matched100v5_plan) as assignment_rows from public.matched100v5_settings where id;
